/**
 * Determines whether an automatic row limit should be appended to a query.
 *
 * This is intentionally conservative to avoid the dashboard accidentally appending a
 * limit to a query that shouldn't have one, without needing a full SQL parser. We only
 * append a limit when the statement is a single, comment-free SELECT that does not
 * already specify a limit.
 */
export function checkIfAppendLimitRequired(sql: string, limit: number = 0) {
  const cleanedSql = sql.trim()

  // Detect an existing LIMIT keyword (case-insensitive, whole word)
  const containsLimit = /\blimit\b/i.test(cleanedSql)

  // Detect line comments
  const containsComment = cleanedSql.includes('--')

  // Detect multiple statements by looking for a semicolon that isn't a trailing one
  const withoutTrailingSemicolons = cleanedSql.replace(/[;\s]+$/, '')
  const containsMultipleStatements = withoutTrailingSemicolons.includes(';')

  // Only SELECT statements are eligible
  const isSelect = /^select\b/i.test(cleanedSql)

  const appendAutoLimit =
    limit > 0 && isSelect && !containsLimit && !containsComment && !containsMultipleStatements

  return { appendAutoLimit }
}

/**
 * Strips any trailing semicolons from the query and appends a single ` limit {n};`,
 * ensuring the resulting string ends with exactly one semicolon.
 */
export function suffixWithLimit(sql: string, limit: number = 0) {
  const cleanedSql = sql.replace(/[;\s]+$/, '')
  return `${cleanedSql} limit ${limit};`
